import{_ as t,D as r,c as n,I as o,j as e,a as i,a4 as s,o as d}from"./chunks/framework.CRCV4hx_.js";const w=JSON.parse('{"title":"Fixed Pricing","description":"","frontmatter":{},"headers":[],"relativePath":"fixed-pricing.md","filePath":"fixed-pricing.md"}'),l={name:"fixed-pricing.md"},c=e("h1",{id:"fixed-pricing",tabindex:"-1"},[i("Fixed Pricing "),e("a",{class:"header-anchor",href:"#fixed-pricing","aria-label":'Permalink to "Fixed Pricing"'},"​")],-1),h=e("p",null,"The Fixed Pricing feature allows you to set a fixed price for a reservation depending on the number of days the reservation lasts. This practice is commonly used in industries like rent a car where the price per day gets lower as the rental duration increases.",-1),p=e("h2",{id:"basics",tabindex:"-1"},[i("Basics "),e("a",{class:"header-anchor",href:"#basics","aria-label":'Permalink to "Basics"'},"​")],-1),f=e("p",null,[i("Using Fixed Pricing is totally optional. To enable it, simply add a "),e("code",null,"Resrv Fixed Pricing"),i(" field to your Blueprint and the relevant section will appear in your Entries.")],-1),u=s('<h2 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h2><p>In the Fixed Pricing field, you can set the total reservation price for the duration of the reservation. In the example above, you want $60 for 2 days, $80 for 3 days, and $100 for 4 days. The <em>extra day</em> price allows you to support more than 4 days for an extra $15 per day.</p><p>Please note that Fixed Pricing only affects the <strong>price</strong> of the reservation. You still need to set up availability using the <a href="./availability">Availability</a> field.</p><p>Also, note that if a duration is missing from the Fixed Pricing field, the system will use the price set in the availability calendar and not fall back to the extra days feature. So, if you delete the 3 days duration from the Fixed Pricing field, the system won&#39;t use the 2 days price plus one extra day, but will fall back to the price set in the Availability field instead.</p><p>Finally, remember that <a href="./dynamic-pricing">Dynamic Pricing</a> also applies to prices set by using the Fixed Pricing field.</p>',5);function _(m,y,g,x,b,P){const a=r("Image");return d(),n("div",null,[c,h,p,f,o(a,{src:"./img/resrv-fixed-pricing.webp",alt:"The Fixed Pricing field in action."}),u])}const F=t(l,[["render",_]]);export{w as __pageData,F as default};
